    /**
     * @throws RuntimeException
     */
    public static function contains(AbstractPlatform $platform, string $identifier): bool
    {
        foreach (self::PLATFORMS as $type => $keywords) {
            if ($platform instanceof $type) {
                return in_array(strtoupper($identifier), explode('|', $keywords), true);
            }
        }
        throw new RuntimeException('No reserved-word dictionary is available for ' . $platform::class);
    }
